pub fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    str1.iter()
        .map(|&c| match c {
            'a'..='z' => ((c as u8) - b'a' + b'A') as char,
            'A'..='Z' => ((c as u8) - b'A' + b'a') as char,
            _ => c,
        })
        .collect()
}